            "fr": "Antioxydant",
            "ru": "Антиоксидант",
            "pl": "Przeciwutleniacz",
            "fi": "Hapettumisenestoaine",
            "sl": "Antioksidant",
            "en": "Antioxidant",
            "de": "Antioxidant",
            "sv": "Antioxidationsmedel"
